  "vector",
  "enum Vector[T] : Nat -> Type {\n  Nil : Vector[T](0)\n  Cons[n : Nat](T, Vector[T](n)) : Vector[T](S(n))\n}\n\nfn[T, n] Vector::head(self : Vector[T](S(n))) -> T {\n  let Cons(hd, _) = self\n  hd\n}\n\nfn[T, n] Vector::tail(self : Vector[T](S(n))) -> Vector[T](n) {\n  match self {\n    Nil\n    Cons(_, tl) => tl\n  }\n}\n\nfn[T, n : Nat, m : Nat] Vector::append(self : Vector[T](n), ys : Vector[T](m)) -> Vector[T](n + m) {\n  match self {\n    Nil => ys\n    Cons(x, xs) => Cons(x, xs.append(ys))\n  }\n}\n\nfn[T, U, n : Nat] Vector::map(self : Vector[T](n), f : (T) -> U) -> Vector[U](n) {\n  match self {\n    Nil => Nil\n    Cons(x, xs) => Cons(f(x), xs.map(f))\n  }\n}\n\nfn[T, n : Nat] Vector::to_list(self : Vector[T](n)) -> List[T] {\n  match self {\n    Nil => List::Nil\n    Cons(x, xs) => List::Cons(x, xs.to_list())\n  }\n}\n\nfn[A, B, n : Nat] zip(xs : Vector[A](n), ys : Vector[B](n)) -> Vector[(A, B)](n) {\n  match (xs, ys) {\n    (Nil, Nil) => Nil\n    (Cons(x, xt), Cons(y, yt)) => Cons((x, y), zip(xt, yt))\n  }\n}\n\nfn main {\n  let v : Vector[Int](3) = Cons(1, Cons(2, Cons(3, Nil)))\n  println(v.head())\n  println(v.tail().head())\n  let w = v.append(v.map(x => x * 10))\n  println(w.to_list())\n  let z = zip(v, v.map(x => x > 1))\n  println(z.tail().head().1)\n}\n"
