  "monad",
  "fn[M : Monad, T, U, V] lift2(f : (T, U) -> V, m : M[T], n : M[U]) -> M[V] {\n  monad {\n    let t <- m\n    let u <- n\n    Monad::pure(f(t, u))\n  }\n}\n\nfn[M : Monad, T, U, V] lift2_nested(f : (T, U) -> V, m : M[T], n : M[U]) -> M[V] {\n  monad {\n    Monad::pure(f(<- m, <- n))\n  }\n}\n\nfn safe_div(a : Int, b : Int) -> Option[Int] {\n  if b == 0 { None } else { Some(a / b) }\n}\n\nfn main {\n  println(lift2((a, b) => a + b, Some(1), Some(2)))\n  println(lift2_nested((a, b) => a + b, Some(1), None))\n  let xs : List[Int] = Cons(1, Cons(2, Nil))\n  let ys : List[Int] = Cons(10, Cons(20, Nil))\n  println(lift2_nested((a, b) => a * b, xs, ys))\n  let r = monad {\n    let x <- safe_div(10, 2)\n    let y <- safe_div(x, 0)\n    Monad::pure(x + y)\n  }\n  println(r)\n}\n"
