  "patterns",
  "// Patterns and conditions: or-patterns, `as`, guards, `is`, `guard` and\n// `catch` without `try`.\n\nenum Shape {\n  Circle(Int)\n  Rect(Int, Int)\n  Square(Int)\n}\n\nfn kind(s : Shape) -> String {\n  match s {\n    Rect(_, _) | Square(_) => \"polygon\"\n    Circle(r) if r > 10 => \"big circle\"\n    Circle(_) => \"circle\"\n  }\n}\n\n// `as` names the whole value; the alternatives of an or-pattern bind the\n// same variables\nfn widest(s : Shape) -> Shape {\n  match s {\n    Rect(w, _) | Square(w) as big if w > 100 => big\n    Rect(w, h) => Rect(w, h)\n    other => other\n  }\n}\n\nfn small(n : Int) -> Bool {\n  n is (1 | 2 | 3)\n}\n\n// the variables of `x is p` are bound in the rest of the `&&` chain and in\n// the branch taken\nfn get(o : Option[Int]) -> Int {\n  if o is Some(x) && x > 5 {\n    x\n  } else {\n    0\n  }\n}\n\nfn length(xs : List[Int]) -> Int {\n  let mut cur = xs\n  let mut n = 0\n  while cur is Cons(_, rest) {\n    n = n + 1\n    cur = rest\n  }\n  n\n}\n\nfn head_or(xs : List[Int], d : Int) -> Int {\n  guard xs is Cons(h, _) else { return d }\n  h\n}\n\n// guards work with dependent matching too\nfn classify(n : Nat) -> String {\n  match n {\n    0 | 1 => \"tiny\"\n    S(S(k)) if k == 5 => \"seven\"\n    _ => \"other\"\n  }\n}\n\nsuberror Oops {\n  Oops(Int)\n}\n\nfn risky(n : Int) -> Int raise Oops {\n  if n < 0 {\n    raise Oops(n)\n  } else {\n    n * 2\n  }\n}\n\nfn safe(n : Int) -> Int {\n  risky(n) catch {\n    Oops(k) => k\n  }\n}\n\nfn describe(n : Int) -> String {\n  try risky(n) catch {\n    Oops(k) if k < -5 => \"very bad\"\n    _ => \"bad\"\n  } noraise {\n    v => \"ok \" + v.to_string()\n  }\n}\n\nfn main {\n  println(kind(Square(1)) + \", \" + kind(Circle(11)) + \", \" + kind(Circle(1)))\n  println(widest(Square(200)) is Square(_))\n  println(\"\\{small(2)} \\{small(5)}\")\n  println(\"\\{get(Some(9))} \\{get(Some(1))} \\{get(None)}\")\n  println(length(Cons(1, Cons(2, Cons(3, Nil)))))\n  println(\"\\{head_or(Nil, 42)} \\{head_or(Cons(5, Nil), 42)}\")\n  println(classify(1) + \" \" + classify(7) + \" \" + classify(9))\n  println(\"\\{safe(3)} \\{safe(-3)}\")\n  println(describe(4) + \", \" + describe(-1) + \", \" + describe(-9))\n  let (a, _) as pair = (1, 2)\n  println(a + pair.1)\n}\n"
