  "syntax",
  "// MoonBit syntax: loops, local recursion, `defer`, cascades, array and\n// range patterns, number literals and multiline strings.\n\n// `loop`: the arms take the loop's values; `continue` gives new ones\nfn sum(n : Int) -> Int {\n  loop n, 0 {\n    0, acc => acc\n    k, acc => continue k - 1, acc + k\n  }\n}\n\n// a loop is an expression: `break v`, or the `nobreak` block\nfn find(xs : Array[Int], v : Int) -> Int {\n  for i, x in xs {\n    if x == v {\n      break i\n    }\n  } nobreak {\n    -1\n  }\n}\n\n// labels: `break outer~` leaves the outer loop\nfn first_pair(n : Int, product : Int) -> String {\n  let mut res = \"none\"\n  outer~: for i = 1; i < n; i = i + 1 {\n    for j = 1; j < n; j = j + 1 {\n      if i * j == product {\n        res = \"\\{i} * \\{j}\"\n        break outer~\n      }\n    }\n  }\n  res\n}\n\n// a local function can call itself\nfn triangle(n : Int) -> Int {\n  fn go(k : Int) -> Int {\n    if k == 0 {\n      0\n    } else {\n      k + go(k - 1)\n    }\n  }\n\n  go(n)\n}\n\n// `defer` runs when the block is left, however it is left\nfn work(n : Int) -> Int {\n  defer println(\"cleanup \\{n}\")\n  if n == 0 {\n    return -1\n  }\n  n * 2\n}\n\nfn describe(xs : Array[Int]) -> String {\n  match xs {\n    [] => \"empty\"\n    [x] => \"one: \\{x}\"\n    [a, .. rest, z] if a == z => \"same ends around \\{rest.length()}\"\n    [a, ..] => \"starts with \\{a}\"\n  }\n}\n\nfn kind(c : Char) -> String {\n  match c {\n    'a'..='z' => \"lower\"\n    'A'..='Z' => \"upper\"\n    '0'..='9' => \"digit\"\n    _ => \"other\"\n  }\n}\n\nfn main {\n  println(sum(10))\n  println(\"\\{find([5, 7, 9], 9)} \\{find([5, 7, 9], 4)}\")\n  println(first_pair(10, 12))\n  println(triangle(10))\n  println(work(3))\n  println(work(0))\n  println(describe([3, 1, 2, 3]))\n  println(describe([4, 1]))\n  println(kind('q') + \" \" + kind('Q') + \" \" + kind('5'))\n  let xs : Array[Int] = []\n  println(xs..push(1)..push(2).length())\n  println(0b1010 + 0o17 + 0xFF)\n  let text =\n    #|two lines,\n    $|the second with \\{sum(3)}\n  println(text)\n}\n"
